const f = $('Build Forecast Dataset').first().json;
const AR = { CRITICAL: 'حرج', LOW: 'منخفض', REORDER: 'إعادة طلب', OK: 'سليم' };
const all = [...(f.critical_items || []), ...(f.low_stock_items || []), ...(f.reorder_items || [])];
const seen = new Set();
const today = String(f.report_date).replace(/-/g, '');
return all.filter(i => !seen.has(i.product_id) && seen.add(i.product_id)).map(i => ({ json: {
  'رقم أمر الشراء': 'PO-' + i.product_id + '-' + today,
  'كود المنتج': i.product_id,
  'اسم المنتج': i.product_name,
  'المورد': i.supplier,
  'الكمية المطلوبة': i.reorder_quantity,
  'تكلفة الوحدة': i.unit_cost,
  'التكلفة الإجمالية': Math.round(i.reorder_quantity * i.unit_cost * 100) / 100,
  'الأولوية': AR[i.status],
  'أيام المخزون المتبقية': i.days_of_stock,
  'تاريخ النفاد المتوقع': i.projected_stockout_date,
  'تاريخ الإنشاء': f.report_date,
  'الحالة': 'بانتظار الموافقة'
} }));

